syntax:
class ClassName {
public:
    // Constructors
    ClassName();
    // Member functions
    void memberFunction();
private:
    // Data members
    DataType dataMember;
};

code_example:
#include <iostream>

class Point {
public:
    // Constructor
    Point(double x, double y) : x_(x), y_(y) {}
    // Member function
    void display() const {
        std::cout << "Point(" << x_ << ", " << y_ << ")" << std::endl;
    }
private:
    double x_;
    double y_;
};

int main() {
    Point p(3.5, 4.2);
    p.display();
    return 0;
}
